}}
.gov-dot {{
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-top: 5px;
  flex-shrink: 0;
}}
.gov-info {{ flex: 1; min-width: 0; }}
.gov-title {{ font-size: 12px; font-weight: 500; color: var(--text); }}
